'use client'

import { useCallback, useEffect, useState } from 'react'
import ModeratorShell, { useModeratorAuth } from '../ModeratorShell'

type Buyer = { name: string; phone: string | null; order_count: number; total_spend: number; last_order_at: string | null; account_id: string | null; suspended: boolean; suspended_reason?: string | null }
type Intent = {
  id: string
  crop_name: string | null
  quantity_kg: number | null
  needed_by_date: string | null
  delivery_location: string | null
  requester_name: string | null
  requester_phone: string | null
  created_at: string
}

function fmtDate(iso: string | null): string {
  if (!iso) return '—'
  try { return new Date(iso).toLocaleDateString('en-IN', { day: 'numeric', month: 'short' }) } catch { return '—' }
}

export default function ModeratorConsumersPage() {
  const { zone, checked } = useModeratorAuth()
  const [buyers, setBuyers] = useState<Buyer[]>([])
  const [intents, setIntents] = useState<Intent[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')
  const [busyId, setBusyId] = useState<string | null>(null)

  const load = useCallback(async () => {
    setLoading(true)
    const r = await fetch('/api/moderator/consumers', { credentials: 'same-origin' }).catch(() => null)
    setLoading(false)
    if (!r) { setError('Network error.'); return }
    const json = await r.json().catch(() => ({}))
    if (!r.ok) { setError(json?.error ?? 'Could not load consumers.'); return }
    setBuyers((json.buyers ?? []) as Buyer[])
    setIntents((json.intents ?? []) as Intent[])
  }, [])

  useEffect(() => { if (checked) void load() }, [checked, load])

  const toggleSuspend = async (b: Buyer) => {
    if (busyId || !b.account_id) return
    const next = !b.suspended
    // Suspending requires a mandatory reason; the buyer sees it when they try
    // to log in, and it shows here in red for other moderators.
    let reason = ''
    if (next) {
      const entered = window.prompt(`Reason for suspending ${b.name}?\nసస్పెండ్ చేయడానికి కారణం? (e.g. Multiple fake orders)`)
      if (entered === null) return // cancelled
      reason = entered.trim()
      if (!reason) { setError('A reason is required to suspend an account.'); return }
    }
    setBusyId(b.account_id)
    setError('')
    const r = await fetch(`/api/moderator/consumers/${b.account_id}`, {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      credentials: 'same-origin',
      body: JSON.stringify({ suspended: next, reason }),
    }).catch(() => null)
    setBusyId(null)
    if (!r || !r.ok) {
      const j = r ? await r.json().catch(() => ({})) : {}
      setError(j?.error ?? 'Update failed.'); return
    }
    setBuyers((list) => list.map((x) => (x.account_id === b.account_id ? { ...x, suspended: next, suspended_reason: next ? reason : null } : x)))
  }

  const markFulfilled = async (it: Intent) => {
    if (busyId) return
    setBusyId(it.id)
    const r = await fetch(`/api/moderator/demand-intents/${it.id}`, {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      credentials: 'same-origin',
      body: JSON.stringify({ fulfilled: true }),
    }).catch(() => null)
    setBusyId(null)
    if (!r || !r.ok) {
      const j = r ? await r.json().catch(() => ({})) : {}
      setError(j?.error ?? 'Update failed.'); return
    }
    setIntents((list) => list.filter((x) => x.id !== it.id))
    // Offer to nudge the requester on WhatsApp that the crop is available.
    if (it.requester_phone) {
      const msg = encodeURIComponent(
        `Good news! ${it.crop_name ?? 'What you asked for'} is now available in your area on GoGrameen. Order here: gogrameen.in/consumer`,
      )
      window.open(`https://wa.me/91${it.requester_phone}?text=${msg}`, '_blank', 'noopener')
    }
  }

  if (!checked || !zone) {
    return (
      <main className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="w-10 h-10 border-4 border-green-700 border-t-transparent rounded-full animate-spin" />
      </main>
    )
  }

  return (
    <ModeratorShell title="Consumers" subtitle="Buyers in your zone and open demand requests" zone={zone}>
      {error && (
        <div className="bg-red-50 border border-red-200 text-red-700 rounded-xl px-4 py-2 text-sm font-semibold mb-4">{error}</div>
      )}

      {loading ? (
        <p className="text-sm text-gray-400 py-10 text-center">Loading…</p>
      ) : (
        <div className="space-y-6">
          {/* Open demand intents */}
          <section>
            <h2 className="text-[11px] font-bold text-gray-400 uppercase tracking-wide mb-2">
              Open demand · {intents.length}
            </h2>
            {intents.length === 0 ? (
              <div className="text-center py-10 bg-white rounded-2xl border border-gray-100">
                <p className="text-sm text-gray-400">No open requests right now.</p>
              </div>
            ) : (
              <div className="space-y-3">
                {intents.map((it) => (
                  <div key={it.id} className="bg-white rounded-2xl border border-gray-100 p-4 shadow-sm">
                    <div className="flex items-start justify-between gap-3">
                      <div className="min-w-0">
                        <p className="font-bold text-gray-900 text-sm">
                          {it.crop_name ?? 'Crop'}{it.quantity_kg ? ` · ${it.quantity_kg} kg` : ''}
                        </p>
                        <p className="text-xs text-gray-500 mt-0.5">
                          {it.requester_name ?? 'Someone'}{it.delivery_location ? ` · ${it.delivery_location}` : ''}
                        </p>
                        <p className="text-[11px] text-gray-400 mt-0.5">Needed by {fmtDate(it.needed_by_date)}</p>
                      </div>
                      <button
                        onClick={() => markFulfilled(it)}
                        disabled={busyId === it.id}
                        className="bg-green-700 text-white text-xs font-bold px-3 py-1.5 rounded-lg active:bg-green-800 disabled:opacity-50 whitespace-nowrap"
                      >
                        Mark fulfilled
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </section>

          {/* Top buyers */}
          <section>
            <h2 className="text-[11px] font-bold text-gray-400 uppercase tracking-wide mb-2">
              Buyers · {buyers.length}
            </h2>
            {buyers.length === 0 ? (
              <div className="text-center py-10 bg-white rounded-2xl border border-gray-100">
                <p className="text-sm text-gray-400">No orders in your zone yet.</p>
              </div>
            ) : (
              <div className="bg-white rounded-2xl border border-gray-100 shadow-sm divide-y divide-gray-100">
                <div className="grid grid-cols-[1fr_auto_auto] gap-3 px-4 py-2 text-[11px] font-bold text-gray-400 uppercase tracking-wide bg-gray-50">
                  <span>Buyer</span>
                  <span className="w-14 text-right">Orders</span>
                  <span className="w-20 text-right">Spend</span>
                </div>
                {buyers.map((b, i) => (
                  <div key={`${b.phone ?? b.name}-${i}`} className="px-4 py-3">
                    <div className="grid grid-cols-[1fr_auto_auto] gap-3 items-center">
                      <div className="min-w-0">
                        <p className="font-bold text-gray-900 text-sm truncate flex items-center gap-1.5">
                          {b.name}
                          {b.suspended && (
                            <span className="text-[10px] font-bold text-red-600 bg-red-50 border border-red-200 rounded px-1.5 py-0.5 uppercase tracking-wide">Suspended</span>
                          )}
                        </p>
                        {b.phone && <a href={`tel:+91${b.phone}`} className="text-[11px] text-green-700">+91 {b.phone}</a>}
                        {b.suspended && b.suspended_reason && (
                          <p className="mt-1 text-[11px] text-red-700 bg-red-50 border border-red-200 rounded-lg px-2 py-1 leading-snug">
                            🚫 Account suspended: {b.suspended_reason}
                          </p>
                        )}
                      </div>
                      <span className="w-14 text-right text-sm text-gray-600">{b.order_count}</span>
                      <span className="w-20 text-right text-sm font-semibold text-gray-900">₹{b.total_spend}</span>
                    </div>
                    {b.account_id && (
                      <div className="mt-2 flex justify-end">
                        <button
                          onClick={() => toggleSuspend(b)}
                          disabled={busyId === b.account_id}
                          className={`text-[11px] font-bold px-2.5 py-1 rounded-lg disabled:opacity-50 ${
                            b.suspended
                              ? 'text-green-700 border border-green-300 active:bg-green-50'
                              : 'text-red-600 border border-red-300 active:bg-red-50'
                          }`}
                        >
                          {busyId === b.account_id ? '…' : b.suspended ? 'Reactivate' : 'Suspend'}
                        </button>
                      </div>
                    )}
                  </div>
                ))}
              </div>
            )}
          </section>
        </div>
      )}
    </ModeratorShell>
  )
}

import { createClient } from '@supabase/supabase-js'
import { NextRequest, NextResponse } from 'next/server'
import { isModeratorRequest, getModeratorZone } from '@/lib/moderator-session'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i

function svc() {
  return createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!,
  )
}

// PATCH — suspend or reactivate a consumer account.
//   { suspended: true | false }
// A moderator may only act on a consumer who has ordered from a farmer in their
// zone, so one zone's moderator can't touch another zone's buyers.
export async function PATCH(req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  if (!isModeratorRequest(req)) {
    return NextResponse.json({ error: 'Moderator login required.' }, { status: 401 })
  }
  const { id } = await params
  if (!id || !UUID_RE.test(id)) return NextResponse.json({ error: 'Invalid consumer id.' }, { status: 400 })

  const body = await req.json().catch(() => null)
  const suspended = (body as { suspended?: unknown })?.suspended
  if (typeof suspended !== 'boolean') {
    return NextResponse.json({ error: 'suspended must be true or false.' }, { status: 400 })
  }
  // A reason is mandatory when suspending so the buyer (and other moderators)
  // can see why. Cleared automatically on reactivation.
  const reasonRaw = (body as { reason?: unknown })?.reason
  const reason = typeof reasonRaw === 'string' ? reasonRaw.trim() : ''
  if (suspended && !reason) {
    return NextResponse.json({ error: 'A reason is required to suspend an account.' }, { status: 400 })
  }

  const zone = getModeratorZone(req)
  const supabase = svc()

  // Confirm the consumer exists.
  const { data: consumer } = await supabase
    .from('consumers_auth').select('id').eq('id', id).maybeSingle()
  if (!consumer) return NextResponse.json({ error: 'Consumer not found.' }, { status: 404 })

  // Zone check: the consumer must have at least one order from a farmer here.
  const { data: zoneFarmers } = await supabase.from('farmers').select('id').eq('region_slug', zone)
  const farmerIds = (zoneFarmers ?? []).map((f) => f.id)
  let inZone = false
  if (farmerIds.length > 0) {
    const { count } = await supabase
      .from('orders')
      .select('id', { count: 'exact', head: true })
      .eq('consumer_id', id)
      .in('farmer_id', farmerIds)
    inZone = (count ?? 0) > 0
  }
  if (!inZone) {
    return NextResponse.json({ error: 'This consumer has not ordered in your zone.' }, { status: 403 })
  }

  const { error } = await supabase
    .from('consumers_auth')
    .update({
      suspended,
      suspended_at: suspended ? new Date().toISOString() : null,
      suspended_reason: suspended ? reason : null,
    })
    .eq('id', id)
  if (error) {
    console.error('[YFF moderator/consumers PATCH] update failed:', error.message)
    return NextResponse.json({ error: error.message }, { status: 500 })
  }
  return NextResponse.json({ id, suspended, suspended_reason: suspended ? reason : null })
}

import { createClient } from '@supabase/supabase-js'
import { NextRequest, NextResponse } from 'next/server'
import { getConsumerSessionFromRequest, clearSessionCookie } from '@/lib/session'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

export async function GET(req: NextRequest) {
  const session = getConsumerSessionFromRequest(req)
  if (!session) {
    return NextResponse.json({ consumer: null }, { status: 200 })
  }

  const supabase = createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!,
  )

  const { data: user } = await supabase
    .from('consumers_auth')
    .select('id, name, phone, suspended')
    .eq('id', session.consumerId)
    .maybeSingle()

  if (!user || user.suspended === true) {
    // Cookie references a deleted or suspended account — clear it so the
    // client logs out on its next check.
    const res = NextResponse.json({ consumer: null }, { status: 200 })
    clearSessionCookie(res)
    return res
  }

  return NextResponse.json({ consumer: { id: user.id, name: user.name, phone: user.phone } })
}

import { createClient } from '@supabase/supabase-js'
import { NextRequest, NextResponse } from 'next/server'
import { verifyPassword } from '@/lib/password'
import { normalizePhone } from '@/lib/phone'
import { setSessionCookie } from '@/lib/session'
import { rateLimit } from '@/lib/rate-limit'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

export async function POST(req: NextRequest) {
  const body = await req.json().catch(() => null)
  if (!body || typeof body !== 'object') {
    return NextResponse.json({ error: 'Invalid request.' }, { status: 400 })
  }

  const phone = normalizePhone(body.phone)
  const password = String(body.password ?? '')

  if (!phone) {
    return NextResponse.json({ error: 'Enter a valid 10-digit phone number.' }, { status: 400 })
  }
  if (!password) {
    return NextResponse.json({ error: 'Enter your password.' }, { status: 400 })
  }

  // Brute-force throttle: 5 login attempts per phone per 10 min, plus 30 / IP
  const ip = req.headers.get('x-forwarded-for')?.split(',')[0]?.trim() || 'unknown'
  if (
    !rateLimit(`login:phone:${phone}`, 5, 10 * 60 * 1000) ||
    !rateLimit(`login:ip:${ip}`, 30, 10 * 60 * 1000)
  ) {
    return NextResponse.json(
      { error: 'Too many login attempts. Please try again in a few minutes.' },
      { status: 429 },
    )
  }

  const supabase = createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!,
  )

  const { data: user, error: lookupErr } = await supabase
    .from('consumers_auth')
    .select('id, name, phone, password_hash, suspended, suspended_reason')
    .eq('phone', phone)
    .maybeSingle()

  if (lookupErr) {
    console.error('[YFF login] lookup failed:', lookupErr.code, lookupErr.message)
    if (
      lookupErr.message?.includes('does not exist')
      || lookupErr.code === '42P01'
    ) {
      return NextResponse.json(
        { error: 'consumers_auth table is missing. Run scripts/consumer-auth-migration.sql in Supabase first.' },
        { status: 500 },
      )
    }
    return NextResponse.json(
      { error: `Database error: ${lookupErr.message}` },
      { status: 500 },
    )
  }

  // Anti-enumeration: same generic error whether the phone exists or not.
  const wrongCreds = NextResponse.json(
    { error: 'Wrong phone or password. / తప్పు ఫోన్ లేదా పాస్‌వర్డ్.' },
    { status: 401 },
  )

  if (!user) return wrongCreds
  if (!user.password_hash || !verifyPassword(password, user.password_hash)) return wrongCreds

  // Suspended accounts can't sign in. Checked only after a correct password so
  // it doesn't leak which numbers are registered.
  if (user.suspended === true) {
    const reason = (user.suspended_reason as string | null)?.trim()
    return NextResponse.json(
      {
        error: reason
          ? `Account suspended: ${reason}. Please contact support. / ఖాతా నిలిపివేయబడింది: ${reason}.`
          : 'This account has been suspended. Please contact support. / ఈ ఖాతా నిలిపివేయబడింది.',
      },
      { status: 403 },
    )
  }

  await supabase
    .from('consumers_auth')
    .update({ last_login_at: new Date().toISOString() })
    .eq('id', user.id)

  const res = NextResponse.json({
    ok: true,
    consumer: { id: user.id, name: user.name, phone: user.phone },
  })
  try {
    setSessionCookie(res, user.id)
  } catch (e) {
    const msg = e instanceof Error ? e.message : 'Session setup failed.'
    console.error('[YFF login] setSessionCookie failed:', msg)
    return NextResponse.json({ error: msg }, { status: 500 })
  }
  return res
}

'use client'

import Link from 'next/link'
import { useEffect, useRef, useState } from 'react'
import { useLang } from '@/lib/LanguageContext'
import LanguageToggle from '@/components/LanguageToggle'
import { useConsumerAuth } from '@/lib/ConsumerAuthContext'

type ActiveTab = 'consumer' | 'farmer' | 'delivery' | 'moderator'

export default function GlobalNav({ activeTab = 'consumer' }: { activeTab?: ActiveTab }) {
  const { tx } = useLang()
  const { state, consumer, openAuth, logout } = useConsumerAuth()

  const tabs = [
    { key: 'consumer' as const, href: '/consumer', label: tx.consumerNav },
    { key: 'farmer' as const, href: '/farmer/dashboard', label: tx.farmerNav },
    { key: 'delivery' as const, href: '/rider', label: tx.deliveryNav },
    { key: 'moderator' as const, href: '#', label: tx.moderatorNav, disabled: true },
  ]

  return (
    <nav className="sticky top-0 z-50 bg-green-900 shadow-lg">
      {/* Logo row */}
      <div className="flex items-center justify-between px-4 py-3 border-b border-green-800 gap-2">
        <Link href="/consumer" className="flex items-center gap-2.5 min-w-0">
          <div className="w-9 h-9 bg-green-700 rounded-xl flex items-center justify-center flex-shrink-0">
            <span className="text-white font-black text-xs">YFF</span>
          </div>
          <div className="leading-tight min-w-0">
            <span className="text-white font-bold text-sm block truncate">YourFamilyFarmer</span>
            <span className="text-green-400 text-[11px] block truncate">యువర్ ఫ్యామిలీ ఫార్మర్</span>
          </div>
        </Link>

        <div className="flex items-center gap-2.5 flex-shrink-0">
          {state.status === 'loading' ? null : consumer ? (
            <ConsumerMenu name={consumer.name} onLogout={logout} />
          ) : (
            <button
              onClick={openAuth}
              className="text-[11px] font-bold text-green-100 bg-green-800 active:bg-green-700 rounded-full px-3 py-1.5 leading-tight"
            >
              Login / లాగిన్
            </button>
          )}
          <LanguageToggle />
        </div>
      </div>

      {/* Role tabs */}
      <div className="flex">
        {tabs.map((tab) => {
          const isActive = tab.key === activeTab

          if (tab.disabled) {
            return (
              <span key={tab.key} className="flex-1 text-center py-2.5 text-xs text-green-700 font-medium">
                {tab.label}
              </span>
            )
          }

          return (
            <Link
              key={tab.key}
              href={tab.href}
              className={`flex-1 text-center py-2.5 text-xs font-bold transition-colors ${
                isActive
                  ? 'bg-green-700 text-white border-b-2 border-green-300'
                  : 'text-green-300 hover:text-white'
              }`}
            >
              {tab.label}
            </Link>
          )
        })}
      </div>
    </nav>
  )
}

function ConsumerMenu({ name, onLogout }: { name: string | null; onLogout: () => Promise<void> }) {
  const [open, setOpen] = useState(false)
  const wrapRef = useRef<HTMLDivElement>(null)
  const firstName = (name ?? '').split(' ')[0] || 'there'

  useEffect(() => {
    if (!open) return
    const onDocClick = (e: MouseEvent) => {
      if (!wrapRef.current?.contains(e.target as Node)) setOpen(false)
    }
    const onEsc = (e: KeyboardEvent) => { if (e.key === 'Escape') setOpen(false) }
    document.addEventListener('mousedown', onDocClick)
    document.addEventListener('keydown', onEsc)
    return () => {
      document.removeEventListener('mousedown', onDocClick)
      document.removeEventListener('keydown', onEsc)
    }
  }, [open])

  return (
    <div ref={wrapRef} className="relative">
      <button
        onClick={() => setOpen((v) => !v)}
        aria-haspopup="menu"
        aria-expanded={open}
        className="text-[11px] font-bold text-green-100 bg-green-800 active:bg-green-700 rounded-full px-3 py-1.5 leading-tight max-w-[104px] truncate"
      >
        Hi {firstName} ▾
      </button>
      {open && (
        <div
          role="menu"
          className="absolute right-0 mt-2 w-56 bg-white rounded-2xl shadow-xl border border-gray-100 py-1.5 text-sm z-50"
        >
          <p className="px-4 py-2 text-[11px] text-gray-500 leading-tight border-b border-gray-100 mb-1">
            Logged in as<br />
            <span className="text-gray-800 font-semibold">{name || 'Consumer'}</span>
          </p>
          <Link
            href="/consumer/orders"
            onClick={() => setOpen(false)}
            className="block px-4 py-2.5 text-gray-800 active:bg-gray-100 font-semibold"
          >
            🧾 My orders / నా ఆర్డర్లు
          </Link>
          <Link
            href="/consumer"
            onClick={() => setOpen(false)}
            className="block px-4 py-2.5 text-gray-800 active:bg-gray-100"
          >
            🛒 Browse / కొనుగోలు
          </Link>
          <button
            onClick={() => { setOpen(false); void onLogout() }}
            className="block w-full text-left px-4 py-2.5 text-red-600 active:bg-red-50 font-semibold border-t border-gray-100 mt-1"
          >
            ↪ Log out / లాగౌట్
          </button>
        </div>
      )}
    </div>
  )
}

'use client'

import { createContext, useCallback, useContext, useEffect, useRef, useState, ReactNode } from 'react'
import dynamic from 'next/dynamic'

export type Consumer = { id: string; name: string | null; phone: string }

type AuthState =
  | { status: 'loading'; consumer: null }
  | { status: 'authenticated'; consumer: Consumer }
  | { status: 'anonymous'; consumer: null }

type LoginPayload = { phone: string; password: string }
type RegisterPayload = { name: string; phone: string; password: string }
type AuthResult = { ok: true } | { ok: false; error: string }

type ConsumerAuthContextValue = {
  state: AuthState
  consumer: Consumer | null
  /**
   * Run `action` immediately when authenticated; otherwise open the auth modal
   * and run `action` after a successful login or registration.
   */
  requireAuth: (action: () => void) => void
  login: (payload: LoginPayload) => Promise<AuthResult>
  register: (payload: RegisterPayload) => Promise<AuthResult>
  logout: () => Promise<void>
  openAuth: () => void
  closeAuth: () => void
}

const STORAGE_KEY = 'REDACTED'
const AUTH_EVENT = 'yff:consumer-auth-change'

const ConsumerAuthContext = createContext<ConsumerAuthContextValue | null>(null)

// Modal is loaded only when first opened, keeping the initial consumer page light
const AuthModal = dynamic(() => import('@/components/consumer/AuthModal'), { ssr: false })

function readCachedConsumer(): Consumer | null {
  if (typeof window === 'undefined') return null
  try {
    const raw = localStorage.getItem(STORAGE_KEY)
    if (!raw) return null
    const parsed = JSON.parse(raw)
